projects=[]
for item in items:
    code=f"P{item['n']:03}"
    record=json.loads((OUT/f'source/{code}.json').read_text(encoding='utf-8'))
    import re
    links=re.findall(r'/url: (https?://[^\s]+)',record['snapshot'])
    external=next((s for s in links if 'notion.site' not in s),None)
    if external and external.startswith('http:'): external=external.replace('http:','https:',1)
    media=[]
    metadata=json.loads((RAW/code/'source.json').read_text())
    for pos,(index,ar,en) in enumerate(item['images']):
        image=Image.open(RAW/code/f'{index:02}.png').convert('RGB')
        image.thumbnail((1600,1600),Image.Resampling.LANCZOS)
        directory=OUT/'images'/item['slug']; directory.mkdir(parents=True,exist_ok=True)
        file=directory/('cover.jpg' if pos==0 else f'gallery-{pos:02}.jpg')
        image.save(file,quality=90,optimize=True)
        media.append({'file':file.relative_to(OUT).as_posix(),'alt':bi(ar,en),'sourceUrl':metadata[index]['sourceUrl'],'sha256':hashlib.sha256(file.read_bytes()).hexdigest(),'bytes':file.stat().st_size})
    content={k:item[k] for k in ['title','summary','body','contribution']}
    content['body']={lang:item['body'][lang]+'\n\n## '+('الوظائف الأساسية' if lang=='ar' else 'Key features')+'\n'+'\n'.join('- '+f[lang] for f in item['features'])+(('\n\n[زيارة موقع المشروع]('+external+')' if lang=='ar' else '\n\n[Visit project website]('+external+')') if external else '') for lang in ['ar','en']}
    content.update(categoryId=item['cat'],slug=item['slug'],usage='demo',attribution='company',mediaIds=[],links=[],order=item['n']-1,year=None)
    projects.append({'sourceId':code,'projectId':f"yogen-p{item['n']:03}",'sourceUrl':record['url'],'content':content,'media':media,'editorial':{'externalUrl':external,'features':item['features'],'usageNote':'The user confirmed a mix of real projects and demos; individual classification is pending, so unspecified cases remain demo.','attributionEvidence':'The user identified these as company projects.','technologyNote':'No stack or execution year is inferred.','imageSelection':'Original source screens selected without private individual records.'}})
catalog={'version':1,'site':'yogen','source':'https://hail-bosworth-a45.notion.site/3dcc5f5ba7f18069859ecbb8ff9380a8?v=3dcc5f5ba7f1806f8273000c0cfd49ca','categories':[{'id':id,'name':bi(ar,en),'order':i,'enabled':True} for i,(id,ar,en) in enumerate(categories)],'projects':projects}
if (OUT/'projects.json').exists():
    previous={p['projectId']:p for p in json.loads((OUT/'projects.json').read_text(encoding='utf-8'))['projects']}
    for project in projects:
        old=previous.get(project['projectId'])
        if old and [(m['file'],m['sha256']) for m in old['media']]==[(m['file'],m['sha256']) for m in project['media']]:
            project['content']['mediaIds']=old['content'].get('mediaIds',[])
            for media,prior in zip(project['media'],old['media']):
                for key in ['publishedAssetId','publicUrl']:
                    if key in prior: media[key]=prior[key]
(OUT/'projects.json').write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
cards=[]
def review_markdown(text):
    import re
    output=[]
    in_list=False
    for line in text.splitlines():
        safe=html.escape(line)
        safe=re.sub(r'\[([^\]]+)\]\((https://[^)]+)\)',r'<a href="\2">\1</a>',safe)
        if line.startswith('- '):
            if not in_list: output.append('<ul>'); in_list=True
            output.append('<li>'+safe[2:]+'</li>')
            continue
        if in_list: output.append('</ul>'); in_list=False
        if line.startswith('## '): output.append('<h3>'+safe[3:]+'</h3>')
        elif line.strip(): output.append('<p>'+safe+'</p>')
    if in_list: output.append('</ul>')
    return ''.join(output)
for p in projects:
    c=p['content']; esc=html.escape
    gallery=''.join(f'<figure><img src="{esc(m["file"])}" alt="{esc(m["alt"]["ar"])}" loading="lazy"><figcaption>{esc(m["alt"]["ar"])}</figcaption></figure>' for m in p['media'])
    features=''.join(f'<li>{esc(f["ar"])}</li>' for f in p['editorial']['features'])
    cards.append(f'<article id="{c["slug"]}"><small>{p["sourceId"]} · {c["categoryId"]}</small><h2>{esc(c["title"]["ar"])}</h2><p class="en" dir="ltr">{esc(c["title"]["en"])}</p><p class="summary">{esc(c["summary"]["ar"])}</p><div class="gallery">{gallery}</div><div class="body">{review_markdown(c["body"]["ar"])}</div><p><strong>دور الشركة:</strong> {esc(c["contribution"]["ar"])}</p><details><summary>English content</summary><div dir="ltr"><p>{esc(c["summary"]["en"])}</p><div class="body">{review_markdown(c["body"]["en"])}</div><p>{esc(c["contribution"]["en"])}</p></div></details><a href="{esc(p["sourceUrl"])}">المصدر في Notion</a></article>')
